ECONOMIC_COMPENSATION.conversion:
const start = get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from);
const end = add_days(ctx.entry.incurred_on, 1);
const months = calendar_completed_months(start, end);
const years = Math.trunc(months / 12);
const remainder = months % 12;
const part =
	remainder >= 6 ? 1 :
	remainder > 0 || add_months(start, months) < end ? 0.5 :
	0;
const count = years + part;
// 劳动合同法 第四十七条第二款: the 3× wage and the 12-year cap bind only a wage above 3× the local monthly average
const wage = Number(ctx.entry.quantity);
const code = get(
	ctx.subject.employer,
	'statutory_parameters.region',
	get(ctx.subject.employer, 'source_reference', '')
);
const cap = first(ctx.lookup.average_wage_cap.filter((row) => row.code === code));
if (wage <= cap.monthly) return wage * count;
return cap.monthly * Math.min(12, count);

DAMAGE_COMPENSATION_DEDUCTION.conversion:
// 工资支付暂行规定 第十六条: 每月扣除的部分不得超过劳动者当月工资的20%, 扣除后的剩余工资不得低于当地月最低工资标准
const wage = Number(ctx.month_wage ?? get(ctx.subject.employment, 'terms.rate.amount', 0));
if (!(wage > 0)) return ctx.entry.quantity;
const ext = get(ctx.subject.employer, 'statutory_parameters', {});
const employerRegion = String(get(ext, 'region', ''));
const worksite = String(get(ctx.subject.employment, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
const zone = worksite !== '' && worksite !== employerRegion
	? String(get((ctx.lookup.minimum_wage_by_zone || []).find((row) => row.region === region), 'default_zone', '1'))
	: String(get(ext, 'wage_zone', '1'));
const table = (ctx.lookup.minimum_wage_by_zone || []).find((row) => row.region === region && row.zone === zone);
const floor = Number(get(table, 'monthly', 0));
const cap = Math.min(wage * ctx.lookup.max_share_of_wage, Math.max(0, wage - floor));
return Math.min(ctx.entry.quantity, cap);

UNLAWFUL_TERMINATION_COMPENSATION.conversion:
const start = get(ctx.subject.employment, 'service_started_on', ctx.subject.employment.effective_range.from);
const end = add_days(ctx.entry.incurred_on, 1);
const months = calendar_completed_months(start, end);
const years = Math.trunc(months / 12);
const remainder = months % 12;
const part =
	remainder >= 6 ? 1 :
	remainder > 0 || add_months(start, months) < end ? 0.5 :
	0;
const count = years + part;
// 劳动合同法 第四十七条第二款: the 3× wage and the 12-year cap bind only a wage above 3× the local monthly average
const wage = Number(ctx.entry.quantity);
const code = get(
	ctx.subject.employer,
	'statutory_parameters.region',
	get(ctx.subject.employer, 'source_reference', '')
);
const cap = first(ctx.lookup.average_wage_cap.filter((row) => row.code === code));
if (wage <= cap.monthly) return wage * count * ctx.lookup.multiple;
return cap.monthly * Math.min(12, count) * ctx.lookup.multiple;

NON_COMPETE_COMPENSATION.eligibility:
// 劳动合同法 第二十三条、第二十四条; 法释〔2020〕26号 第三十六条: eligibility gate.
const end = get(ctx.subject.employment.effective_range, 'to');
if (!(ctx.entry.quantity > 0)) return false;
if (end == null) return false;
if (!(ctx.entry.incurred_on > end)) return false;
return ctx.entry.incurred_on <= add_years(end, ctx.lookup.max_years);

STATUTORY_REFUND.eligibility:
// A statutory correction is an adhoc entry on this item: Tax or a contribution overpaid, paid back to the employee.
const end = get(ctx.subject.employment, 'effective_range.to', null);
if (ctx.entry.unit !== 'MONEY') return false;
if (!(ctx.entry.quantity > 0)) return false;
if (end != null && !(ctx.entry.incurred_on <= end)) return false;
return true;

OVERTIME.eligibility:
// 劳动法 第四十四条第一项; 工资支付暂行规定 第十三条第一款第一项; 人社部发〔2025〕2号: Normal working-day overtime hours, paid at the statutory multiplier.
const premiumDay = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const terms = ctx.subject.employment.terms;
if (!['STANDARD', ''].includes(get(terms, 'statutory_work_category', ''))) return false;
if (['PART_TIME', 'CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(get(ctx.subject.employment, 'engagement', 'EMPLOYEE'))) return false;
return sum(get(ctx, 'work.days', []).filter((day) => day.day_type === 'WORK' && !premiumDay(day)).map((day) => get(day, 'overtime_hours', 0))) > 0;

OVERTIME.conversion:
// 劳动法 第四十四条第一项; 工资支付暂行规定 第十三条第一款第一项; 人社部发〔2025〕2号: Normal working-day overtime hours, paid at the statutory multiplier.
const premiumDay = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
return sum(get(ctx, 'work.days', []).filter((day) => day.day_type === 'WORK' && !premiumDay(day)).map((day) => get(day, 'overtime_hours', 0))) * ctx.lookup.multiplier * ctx.hour_rate;

COMPREHENSIVE_OVERTIME.eligibility:
// 工资支付暂行规定 第十三条第三款: Overtime beyond the approved comprehensive-hours review, paid at the statutory multiplier.
const review = get(
	ctx.subject.employment.statutory_parameters,
	'comprehensive_overtime_review',
	null
);
const from = ctx.run.salary_coverage.from;
const to = ctx.run.salary_coverage.to;
const terms = ctx.subject.employment.terms;
if (get(terms, 'statutory_work_category', '') !== 'COMPREHENSIVE') return false;
if (['PART_TIME', 'CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(get(ctx.subject.employment, 'engagement', 'EMPLOYEE'))) return false;
if (review == null) return false;
if (review.month !== from.slice(0, 7)) return false;
if (review.reference === '') return false;
if (!(review.settlement_on >= from)) return false;
if (!(review.settlement_on <= to)) return false;
return Number(review.excess_nonholiday_hours) > 0;

COMPREHENSIVE_OVERTIME.conversion:
// 工资支付暂行规定 第十三条第三款: Overtime beyond the approved comprehensive-hours review, paid at the statutory multiplier.
const review = get(
