return Number(review.excess_nonholiday_hours) * ctx.lookup.multiplier * ctx.hour_rate;

REST_DAY_WORK.eligibility:
// 劳动法 第四十四条第二项; 工资支付暂行规定 第十三条: eligibility gate.
const premiumDay = (day) => {
