return sum(get(ctx, 'work.days', []).filter((day) => ['REST', 'OFF'].includes(day.day_type) && !premiumDay(day)).map((day) => get(day, 'worked_hours', 0))) > 0;

REST_DAY_WORK.conversion:
const premiumDay = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
// 劳动法 第四十四条第二项: 不低于工资的200%; the employer's rest-day hourly multiple stands where it pays more.
return sum(get(ctx, 'work.days', []).filter((day) => ['REST', 'OFF'].includes(day.day_type) && !premiumDay(day)).map((day) => get(day, 'worked_hours', 0))) * Math.max(ctx.lookup.multiplier, Number(get(ctx.subject.employer, 'pay_methods.rest_day_hourly_multiplier', 0))) * ctx.hour_rate;

HOLIDAY_WORK.eligibility:
const premiumDay = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
const terms = ctx.subject.employment.terms;
const category = get(terms, 'statutory_work_category', '');
// 上海市企业工资支付办法 第十三条: 不定时工时制在法定休假节日安排工作的按300%; 工资支付暂行规定 第十三条 excludes it elsewhere
const employerRegion = String(get(ctx.subject.employer, 'statutory_parameters.region', ''));
const worksite = String(get(ctx.subject.employment, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
const shanghaiFlexible = category === 'FLEXIBLE' && region === 'SH';
if (!shanghaiFlexible && !['STANDARD', '', 'COMPREHENSIVE'].includes(category)) return false;
if (['PART_TIME', 'CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(get(ctx.subject.employment, 'engagement', 'EMPLOYEE'))) return false;
return sum(get(ctx, 'work.days', []).filter((day) => premiumDay(day)).map((day) => get(day, 'worked_hours', 0))) > 0;

HOLIDAY_WORK.conversion:
// 劳动法 第四十四条第三项; 工资支付暂行规定 第十三条: Hours worked on a statutory holiday, paid at the statutory holiday multiplier.
const premiumDay = (day) => {
	const kind = get(day, 'holiday_kind', '');
	return kind !== '' && kind !== 'MAKEUP_WORKDAY';
};
return sum(get(ctx, 'work.days', []).filter((day) => premiumDay(day)).map((day) => get(day, 'worked_hours', 0))) * ctx.lookup.multiplier * ctx.hour_rate;

FIXED_ALLOWANCE.conversion:
// 工资支付暂行规定 第十一条、第十二条: no wage for days not worked. A fixed allowance is paid for the days the salary pays: it falls by the period's paid share on its own line, and BASIC stays the salary alone.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
const rate = Number(get(terms, 'rate.amount', 0));
const amount = Number(get(terms, 'allowances.FIXED_ALLOWANCE.amount', 0));
const coverage = ctx.run.salary_coverage;
const off = get(ctx.subject.employer, 'payment_schedule.non_working_weekdays', [0, 6]);
let working = 0;
for (let date = coverage.from; date <= coverage.to; date = add_days(date, 1)) if (!off.includes(weekday(date))) working += 1;
const hours = working * Number(get(terms, 'normal_hours_per_day', 8));
const salary = unit === 'DAILY' ? rate * working : unit === 'HOURLY' ? rate * hours : rate;
return salary > 0 ? amount * ctx.paid_share : amount;

HIGH_TEMPERATURE_ALLOWANCE.eligibility:
// 沪人社规〔2019〕19号 (上海6-9月300元/月); 云人社发〔2013〕98号 (云南每工作日10元)
const employerRegion = String(get(ctx.subject.employer, 'statutory_parameters.region', ''));
const worksite = String(get(ctx.subject.employment, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
const events = (ctx.work_events ?? []).filter((e) => get(e, 'code', '') === 'HIGH_TEMPERATURE');
if (events.length === 0) return false;
if (region === 'KM') {
	const covFrom = ctx.run.salary_coverage.from;
	const covTo = ctx.run.salary_coverage.to;
	return events.some((e) => {
		const from = String(get(e, 'from', ''));
		const to = String(get(e, 'to', null) ?? from);
		return from !== '' && from <= covTo && to >= covFrom;
	});
}
if (region !== ctx.lookup.region) return false;
if (!ctx.lookup.months.includes(Number(ctx.as_of.slice(5, 7)))) return false;
return events.some((event) => {
	const from = String(get(event, 'from', ''));
	const to = get(event, 'to', null);
	return from !== '' && from <= ctx.as_of && ctx.as_of <= String(to ?? from);
});

HIGH_TEMPERATURE_ALLOWANCE.conversion:
// 沪人社规〔2019〕19号 (上海300元/月); 云人社发〔2013〕98号 (云南每工作日10元)
const employerRegion = String(get(ctx.subject.employer, 'statutory_parameters.region', ''));
const worksite = String(get(ctx.subject.employment, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
if (region === 'KM') {
	const events = (ctx.work_events ?? []).filter((e) => get(e, 'code', '') === 'HIGH_TEMPERATURE');
	const off = get(ctx.subject.employer, 'payment_schedule.non_working_weekdays', [0, 6]);
	let days = 0;
	for (let d = ctx.run.salary_coverage.from; d <= ctx.run.salary_coverage.to; d = add_days(d, 1)) {
		if (off.includes(weekday(d))) continue;
		if (events.some((e) => {
			const from = String(get(e, 'from', ''));
			const to = String(get(e, 'to', null) ?? from);
			return from !== '' && from <= d && d <= to;
		})) days += 1;
	}
	return days * ctx.lookup.km_daily;
}
return ctx.lookup.monthly;

PENSION.eligibility:
const engagement = get(ctx.subject.employment, 'engagement', 'EMPLOYEE');
	const excluded = ['PART_TIME', 'INTERN', 'CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(engagement);
	const end = get(ctx.subject.employment, 'effective_range.to', null);
	const ended = end != null && end !== '' && end < ctx.run.salary_coverage.from;
	const exempt = get(ctx.subject.employment, 'statutory_parameters.si_exempt_schemes', []);
	// a monthly charge: an off-cycle run carries only its own items
	if (get(ctx.run, 'kind', 'ON_CYCLE') === 'OFF_CYCLE') return false;
	if (excluded) return false;
	if (ended) return false;
	if (Array.isArray(exempt) && exempt.includes('PENSION')) return false;
	const born = get(ctx.subject.employment, 'payroll.date_of_birth', null);
	if (born == null || born === '') return true;
	// 劳动合同法 第四十四条第二项; 劳动合同法实施条例 第二十一条: the labour contract ends at the statutory retirement age, and the scheme stops
	const category =
		get(ctx.subject.employment, 'payroll.gender', null) === 'FEMALE'
			? get(ctx.subject.employment, 'statutory_parameters.retirement_category', 'FEMALE_50')
			: 'MALE';
	const retirement = ctx.lookup.retirement.find((row) => row.category === category);
	const deferred =
		born < retirement.cutoff
			? 0
			: Math.min(
					retirement.max_deferral_months,
					Math.trunc(calendar_completed_months(retirement.cutoff, month_start(born)) / retirement.birth_months_per_step) + 1
				);
	const retires = add_months(born, retirement.base_years * 12 + deferred);
	return ctx.run.salary_coverage.from < retires;

PENSION.employee_amount:
// 社会保险法 第十二条、第六十条: employee statutory calculation.
const code = get(
		ctx.subject.employer,
		'statutory_parameters.region',
		get(ctx.subject.employer, 'source_reference', '')
	);
	const limit = first(ctx.lookup.si_base.filter((row) => row.code === code));
const term = get(ctx.subject.employment, 'statutory_parameters', {});
	const declared = get(term, 'si_contribution_base', null);
	const basic = Number(get(ctx.subtotals, 'BASIC', 0));
	const fixed = Number(get(ctx.subject.employment, 'terms.allowances.FIXED_ALLOWANCE.amount', 0));
	if (declared == null && basic <= 0 && fixed <= 0) return 0;
	const wage = declared != null ? Number(declared) : basic;
	const base = clamp(Math.max(0, wage), limit.floor, limit.ceiling);
	return base * ctx.lookup.employee_rate;

