UNION_FUND.eligibility:
// 工会法 第四十三条: eligibility gate.
const code = get(
		ctx.subject.employer,
		'statutory_parameters.region',
		get(ctx.subject.employer, 'source_reference', '')
	);
	const rule = get(ctx.lookup.preparatory, code, null);
	if (rule == null) return false;
	if (!(Number(get(ctx.subtotals, 'FOREIGN_ALLOWANCES', 0)) > 0)) return false;
	if (get(ctx.subject.employer, 'statutory_parameters.union_established', false) === true) return true;
	if (rule === 'ORGANISATION') return get(ctx.subject.employer, 'statutory_parameters.union_preparatory', false) === true;
	return rule === 'NO_UNION';

IIT.employee_amount:
// 个人所得税法 第六条、第十一条; 国家税务总局公告2018年第61号 第六条; 财税〔2013〕103号 第一条; 公告2022年第34号
const facts = get(ctx.subject.employment, 'statutory_parameters', {});
const elections = get(facts, 'statutory.IIT', {});
const term = facts;
const paidOn = get(ctx.run, 'pay_date', ctx.run.salary_coverage.to);
const year = paidOn.slice(0, 4);
const paidMonth = paidOn.slice(0, 7);
const d = ctx.lookup.deductions;
const residency = get(ctx.subject.employment, 'terms.residency_status', 'RESIDENT');
const now = (code) => Number(get(ctx.subtotals, code, 0));
const ytd = (code) => Number(get(ctx.balances, 'ytd.' + code, 0));
const schemes = get(ctx.balances, 'statutory_contribution', {});
const paid = (code) => (Object.hasOwn(schemes, code + '.employee') ? Number(schemes[code + '.employee']) : 0);
const tax_bracket = (rows, value) => {
	const row = rows.find((item) => item.up_to == null || value <= item.up_to);
	return row == null ? 0 : Math.max(0, value * Number(row.rate) - Number(row.quick));
};
// 财政部 税务总局公告2023年第29号: foreign allowances exempt instead of special additional deductions, never both
const foreignExempt = get(elections, 'foreign_allowance_exemption', false) === true && ctx.lookup.foreign_exemption_active !== false;
const annualBonus = (read) => read('ANNUAL_BONUS_WAGES') - read('ORDINARY_WAGES');
const taxed = (read) => read(foreignExempt ? 'ADDITIONAL_WAGES' : 'FOREIGN_ALLOWANCES');
// 国税发〔2005〕9号 第三条; 财税〔2018〕164号 第一条; 公告2019年第35号: separate bonus tax once per calendar year only
const bonusAllowed = ctx.lookup.annual_bonus_separate_active !== false;
const separate = bonusAllowed && get(elections, 'annual_bonus_separate', false) === true && paid('IIT_ANNUAL_BONUS') === 0 && annualBonus(now) > 0;
const wages = taxed(now) - (separate ? annualBonus(now) : 0);
if (residency === 'NON_RESIDENT') {
	const share = Number(get(facts, 'china_workday_share', 1));
	// 个人所得税法 第六条第一款第二项: non-resident monthly withholding
	const month = get(ctx, 'balances.month', {});
	const heldIn = (code) => (Object.hasOwn(month, paidMonth + '.' + code) ? Number(month[paidMonth + '.' + code]) : 0);
	const coverage = ctx.run.salary_coverage;
	const wholeMonth = String(coverage.from) === String(month_start(coverage.from)) && String(coverage.to) === String(month_end(coverage.from));
	const splitRun = get(ctx.run, 'kind', '') !== 'OFF_CYCLE' && wholeMonth && heldIn('BASIC') > 0;
	const before = (code) => (splitRun ? 0 : heldIn(code));
	const priorBonus = paid('IIT_ANNUAL_BONUS') > 0 ? before('ANNUAL_BONUS_WAGES') - before('ORDINARY_WAGES') : 0;
	const income = wages + Math.max(0, before(foreignExempt ? 'ADDITIONAL_WAGES' : 'FOREIGN_ALLOWANCES') - priorBonus);
	return tax_bracket(ctx.lookup.monthly_ladder, Math.max(0, income * share - d.monthly_standard)) - before('IIT.employee');
}
const split = (flag) => (flag === true ? d.shared_share : 1);
const housing =
	get(elections, 'housing_loan_interest', false) === true ? d.housing_loan :
	get(elections, 'housing_rent', false) === true ? d.housing_rent :
	0;
const special =
	Number(get(elections, 'children_education_children', 0)) * d.child_education * split(get(elections, 'children_education_split', false)) +
	Number(get(elections, 'infant_care_children', 0)) * d.infant_care * split(get(elections, 'infant_care_split', false)) +
	(get(elections, 'continuing_education_degree', false) === true ? d.continuing_education : 0) +
	housing +
	(get(elections, 'elderly_support_only_child', false) === true
		? d.elderly_sole
		: Math.min(Number(get(elections, 'elderly_support_monthly', 0)), d.elderly_shared));
const ordinary = now('ORDINARY_WAGES');
const regionCode = get(ctx.subject.employer, 'statutory_parameters.region', get(ctx.subject.employer, 'source_reference', ''));
const avgCap = first((ctx.lookup.average_wage_cap || []).filter((row) => row.code === regionCode));
// 财税〔2013〕103号 第一条第(二)项: employee annuity deductible up to 4% of wage base capped at 300% of local prior-year avg wage
const rawAnnuityBase = Number(get(term, 'si_contribution_base', null) != null ? term.si_contribution_base : ordinary);
const annuityBase = avgCap != null ? Math.min(rawAnnuityBase, Number(avgCap.monthly)) : rawAnnuityBase;
const other =
	Math.min(Number(get(elections, 'commercial_health_monthly', 0)), d.commercial_health) +
	Math.min(Number(get(elections, 'annuity_employee_monthly', 0)), d.annuity_share * Math.max(0, annuityBase));
const additional = (foreignExempt ? 0 : special) + other;
const contributions = sum(ctx.lookup.deductible_schemes.map((code) => get(ctx.statutory, code + '.employee', 0)));
const total = (rows, field) => rows.reduce((acc, row) => acc + Number(get(row, field, 0)), 0);
const priorIncome = taxed(ytd) - (paid('IIT_ANNUAL_BONUS') > 0 ? annualBonus(ytd) : 0);
const priorContributions = sum(ctx.lookup.deductible_schemes.map(paid));
const start = get(ctx.subject.employment, 'employment_started_on', get(ctx.subject.employment, 'effective_range.from', year + '-01-01'));
const from = start > year + '-01-01' ? start : year + '-01-01';
const months = Math.max(1, calendar_completed_months(month_start(from), paidOn) + 1);
const declaredPrior = get(term, 'prior_employment', []);
const sameAgent = (Array.isArray(declaredPrior) ? declaredPrior : []).filter(
	(row) => Number(get(row, 'tax_year', 0)) === Number(year) && get(row, 'same_withholding_agent', false) === true
);
const elapsedMonths = Number(paidOn.slice(5, 7));
const periods = Math.min(elapsedMonths, months + total(sameAgent, 'months'));
// 公告2020年第13号: first job in year deducts 5000 x elapsed months of year
const standardMonths = get(elections, 'first_job_in_year', false) === true ? Math.max(periods, elapsedMonths) : periods;
const standard = get(elections, 'prior_year_60000', false) === true ? d.annual_standard : d.monthly_standard * standardMonths;
// 国家税务总局公告2018年第61号 第六条; 公告2022年第34号: YTD cumulative personal-pension (<=12000) & qualification (3600) relief carries through every subsequent month of the tax year
const review = get(elections, 'receipt_deduction_review', null);
let annual = 0;
if (review != null && String(get(review, 'month', '')).slice(0, 4) === year && String(get(review, 'month', '')) <= paidMonth) {
	annual = Math.min(d.personal_pension_annual, Number(get(review, 'personal_pension_paid_ytd', 0)));
	if (!foreignExempt && Math.trunc(Number(get(review, 'qualification_year', 0))) === Math.trunc(Number(year)))
		annual += d.qualification_annual;
}
const cumulative = Math.max(
	0,
	priorIncome +
		total(sameAgent, 'gross_income') +
		wages -
		priorContributions -
		total(sameAgent, 'employee_social_contributions') -
		contributions -
		standard -
		additional * periods -
		annual
);
return tax_bracket(ctx.lookup.annual_ladder, cumulative) - paid('IIT') - total(sameAgent, 'iit_withheld');

IIT_ANNUAL_BONUS.eligibility:
// 国税发〔2005〕9号 第三条; 财税〔2018〕164号 第一条; 公告2019年第35号: separate bonus tax once per calendar year
if (ctx.lookup.annual_bonus_separate_active === false) return false;
const elections = get(ctx.subject.employment, 'statutory_parameters.statutory.IIT', {});
if (get(elections, 'annual_bonus_separate', false) !== true) return false;
const schemes = get(ctx.balances, 'statutory_contribution', {});
const paid = Object.hasOwn(schemes, 'IIT_ANNUAL_BONUS.employee') ? Number(schemes['IIT_ANNUAL_BONUS.employee']) : 0;
if (paid > 0) return false;
return Number(get(ctx.subtotals, 'ANNUAL_BONUS_WAGES', 0)) > Number(get(ctx.subtotals, 'ORDINARY_WAGES', 0));

IIT_ANNUAL_BONUS.employee_amount:
// 财税〔2018〕164号 第一条第(一)项 (居民÷12); 公告2019年第35号 第二条、第三条 (非居民÷6×6)
const residency = get(ctx.subject.employment, 'terms.residency_status', 'RESIDENT');
const now = Math.max(0, Number(get(ctx.subtotals, 'ANNUAL_BONUS_WAGES', 0)) - Number(get(ctx.subtotals, 'ORDINARY_WAGES', 0)));
if (now <= 0) return 0;
if (residency === 'NON_RESIDENT') {
	const share = Number(get(ctx.subject.employment, 'statutory_parameters.china_workday_share', 1));
	const part = (now * share) / 6;
	const row = ctx.lookup.monthly_ladder.find((item) => item.up_to == null || part <= item.up_to);
	return row == null ? 0 : Math.max(0, part * Number(row.rate) - Number(row.quick)) * 6;
}
const row = ctx.lookup.monthly_ladder.find((item) => item.up_to == null || now / 12 <= item.up_to);
return row == null ? 0 : Math.max(0, now * Number(row.rate) - Number(row.quick));

IIT_SEVERANCE.employee_amount:
// 财税〔2018〕164号 第五条第(一)项: Tax on severance paid, withheld separately.
	const code = get(
		ctx.subject.employer,
		'statutory_parameters.region',
		get(ctx.subject.employer, 'source_reference', '')
	);
	const cap = first(ctx.lookup.average_wage_cap.filter((row) => row.code === code));
	const schemes = get(ctx.balances, 'statutory_contribution', {});
	const paid = Object.hasOwn(schemes, 'IIT_SEVERANCE.employee') ? Number(schemes['IIT_SEVERANCE.employee']) : 0;
	const now = Number(get(ctx.subtotals, 'SEVERANCE', 0)) - Number(get(ctx.subtotals, 'GROSS', 0));
	const before = Number(get(ctx.balances, 'ytd.SEVERANCE', 0)) - Number(get(ctx.balances, 'ytd.GROSS', 0));
	const taxable = Math.max(0, before + now - cap.monthly * 12);
	const row = ctx.lookup.annual_ladder.find((item) => item.up_to == null || taxable <= item.up_to);
	return taxable * row.rate - row.quick - paid;

IIT_EARLY_RETIREMENT.employee_amount:
// 财税〔2018〕164号 第五条第(二)项: 按办理提前退休手续至法定离退休年龄之间实际年度数平均分摊, 减除60000元/年后适用综合所得税率表
const paidOn = get(ctx.run, 'pay_date', ctx.run.salary_coverage.to);
const now = Number(get(ctx.subtotals, 'EARLY_RETIREMENT', 0)) - Number(get(ctx.subtotals, 'SEVERANCE', 0));
const before = Number(get(ctx.balances, 'ytd.EARLY_RETIREMENT', 0)) - Number(get(ctx.balances, 'ytd.SEVERANCE', 0));
const totalLump = Math.max(0, before + now);
const schemes = get(ctx.balances, 'statutory_contribution', {});
const paid = Object.hasOwn(schemes, 'IIT_EARLY_RETIREMENT.employee') ? Number(schemes['IIT_EARLY_RETIREMENT.employee']) : 0;
if (totalLump <= 0) return -paid;
const born = get(ctx.subject.employment, 'payroll.date_of_birth', null);
let years = 1;
if (born != null && born !== '') {
	const category = get(ctx.subject.employment, 'payroll.gender', null) === 'FEMALE'
		? get(ctx.subject.employment, 'statutory_parameters.retirement_category', 'FEMALE_50')
		: 'MALE';
	const retirement = ctx.lookup.retirement.find((row) => row.category === category);
	const deferred = born < retirement.cutoff
		? 0
		: Math.min(retirement.max_deferral_months, Math.trunc(calendar_completed_months(retirement.cutoff, month_start(born)) / retirement.birth_months_per_step) + 1);
	const retires = add_months(born, retirement.base_years * 12 + deferred);
	years = Math.max(1, Math.ceil(Math.max(1, calendar_completed_months(paidOn, retires)) / 12));
}
const taxablePerYear = Math.max(0, totalLump / years - ctx.lookup.annual_standard);
const row = ctx.lookup.annual_ladder.find((item) => item.up_to == null || taxablePerYear <= item.up_to);
const tax = row == null ? 0 : Math.max(0, taxablePerYear * Number(row.rate) - Number(row.quick)) * years;
return tax - paid;

IIT_INTERNAL_RETIREMENT.employee_amount:
// 财税〔2018〕164号 第五条第(三)项; 国税发〔1999〕58号: 按离退休剩余月份数平摊确定税率, 并与当月工资合并减除5000元计税
const paidOn = get(ctx.run, 'pay_date', ctx.run.salary_coverage.to);
const lump = Math.max(0, Number(get(ctx.subtotals, 'INTERNAL_RETIREMENT', 0)) - Number(get(ctx.subtotals, 'EARLY_RETIREMENT', 0)));
if (lump <= 0) return 0;
const born = get(ctx.subject.employment, 'payroll.date_of_birth', null);
let months = 1;
if (born != null && born !== '') {
	const category = get(ctx.subject.employment, 'payroll.gender', null) === 'FEMALE'
		? get(ctx.subject.employment, 'statutory_parameters.retirement_category', 'FEMALE_50')
		: 'MALE';
	const retirement = ctx.lookup.retirement.find((row) => row.category === category);
	const deferred = born < retirement.cutoff
		? 0
		: Math.min(retirement.max_deferral_months, Math.trunc(calendar_completed_months(retirement.cutoff, month_start(born)) / retirement.birth_months_per_step) + 1);
	const retires = add_months(born, retirement.base_years * 12 + deferred);
	months = Math.max(1, calendar_completed_months(paidOn, retires));
}
const ordinary = Number(get(ctx.subtotals, 'ORDINARY_WAGES', 0));
const probe = Math.max(0, lump / months + ordinary - ctx.lookup.monthly_standard);
const row = ctx.lookup.monthly_ladder.find((item) => item.up_to == null || probe <= item.up_to);
const totalTax = row == null ? 0 : Math.max(0, (lump + ordinary - ctx.lookup.monthly_standard) * Number(row.rate) - Number(row.quick));
const monthIit = Number(get(ctx.statutory, 'IIT.employee', 0));
return Math.max(0, totalTax - monthIit);

