const key = 'MINIMUM_WAGE:' + ctx.entry.id;
if (ctx.reads.obligation.some((task) => task.occurrence_key === key)) return false;
const run = first(ctx.reads.payroll_run);
if (run == null) return false;
const employment = ctx.subject.employment;
const rate = get(employment.terms, 'rate', null);
if (rate == null) return false;
if (rate.unit !== 'MONTHLY') return false;
if (['PART_TIME', 'INTERN', 'CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(employment.engagement)) return false;
const salary = run.salary_coverage;
if (month_start(salary.from) !== salary.from) return false;
if (month_end(salary.to) !== salary.to) return false;
if (employment.effective_range.from > salary.from) return false;
const end = get(employment.effective_range, 'to', null);
if (end != null && end !== '' && end < salary.to) return false;
const ext = get(ctx.subject.employer, 'statutory_parameters', {});
const employerRegion = String(get(ext, 'region', ''));
const worksite = String(get(employment.terms, 'work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
const zones = ctx.lookup.minimum_wage_by_zone.filter((row) => row.region === region);
if (zones.length === 0) return false;
const zone = worksite !== '' && worksite !== employerRegion
  ? String(zones[0].default_zone)
  : String(get(ext, 'wage_zone', zones[0].default_zone));
const table = zones.find((row) => row.zone === zone);
if (table == null) return false;
const contributions = table.excludes_employee_contributions ? Number(ctx.entry.employee_statutory) : 0;
const fixed = Number(get(employment.terms, 'allowances.FIXED_ALLOWANCE.amount', 0));
return Number(rate.amount) + fixed - contributions < table.monthly;

