MINIMUM_WAGE_HOURLY.validate:
const employer = ctx.subject.employer;
const ext = get(employer, 'statutory_parameters', {});
const terms = get(ctx.entry, 'terms', {});
const employerRegion = String(get(ext, 'region', ''));
const worksite = String(get(terms, 'work_region', ''));
// the place of performance governs; the registered place is the fallback
const region = worksite !== '' ? worksite : employerRegion;
const regionRows = (ctx.lookup.minimum_wage_by_zone ?? []).filter((r) => r.region === region);
const zone = worksite !== '' && worksite !== employerRegion
  ? String(get(regionRows[0], 'default_zone', '1'))
  : String(get(ext, 'wage_zone', get(regionRows[0], 'default_zone', '1')));
const table = regionRows.find((r) => r.zone === zone);
const floor = Number(get(table, 'hourly', 0));
const rate = get(terms, 'rate', {});
const amount = Number(get(rate, 'amount', 0));
const weekly = Number(get(terms, 'normal_hours_per_week', 0)) ||
  Number(get(terms, 'normal_hours_per_day', 8)) * Number(get(terms, 'normal_days_per_week', 5));
const monthlyHours = weekly * 52 / 12;
const hourly = get(rate, 'unit', 'HOURLY') === 'MONTHLY' ? amount / monthlyHours : amount;
return floor > 0 && monthlyHours > 0 && hourly >= floor;

PROBATION_LENGTH.validate:
// Labor Contract Law art.19: compliance validation.
const probation = ctx.entry.terms.probation_period;
const limits = ctx.lookup.probation_months;
const engaged = ctx.entry.engagement === 'PART_TIME';
const signed = ctx.entry.signed_contract_period;
let months = limits.open_ended;
if (engaged) months = 0;
else if (signed != null) {
  const length = calendar_completed_months(signed.from, add_days(signed.to, 1));
  months =
    length < limits.minimum_contract ? 0 :
    length < limits.medium_contract ? limits.short :
    length < limits.long_contract ? limits.medium :
    limits.long;
}
if (!(months > 0)) return false;
if (!(probation.from >= ctx.entry.effective_range.from)) return false;
return probation.to < add_months(probation.from, months);

PROBATION_WAGE.condition:
// Labor Contract Law art.20; Implementing Regulations art.15 Art.20; Regs art.15: trigger condition.
if (get(ctx.entry.terms, 'probation_period', null) == null) return false;
const rate = get(ctx.entry.terms, 'rate', null);
if (rate == null) return false;
return rate.unit === 'MONTHLY';

PROBATION_WAGE.validate:
// 劳动合同法 第二十条; 实施条例 第十五条: 试用期工资不得低于本单位相同岗位最低档工资的80%或者劳动合同约定工资的80%, 且不得低于用人单位所在地的最低工资标准
const employer = ctx.subject.employer;
const ext = ctx.entry.statutory_parameters ?? {};
const job = get(ext, 'job_salary', null);
const jobValue = job == null ? null : typeof job === 'number' ? job : Number(get(job, 'value', job));
const post = get(ext, 'post_lowest_wage', null);
const postValue = post == null ? null : Number(post);
const rate = Number(ctx.entry.terms.rate.amount);
const share = ctx.lookup.probation_wage_share;
const comparable =
	jobValue != null && postValue != null ? Math.min(Number(jobValue), postValue) * share :
	jobValue != null ? Number(jobValue) * share :
	postValue != null ? postValue * share :
	null;
const employerExt = get(employer, 'statutory_parameters', {});
const employerRegion = String(get(employerExt, 'region', ''));
const worksite = String(get(ctx.entry.terms, 'work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
const regionRows = (ctx.lookup.minimum_wage_by_zone ?? []).filter((r) => r.region === region);
const zone = worksite !== '' && worksite !== employerRegion
	? String(get(regionRows[0], 'default_zone', '1'))
	: String(get(employerExt, 'wage_zone', get(regionRows[0], 'default_zone', '1')));
const table = regionRows.find((r) => r.zone === zone);
const floor = Number(get(table, 'monthly', 0));
if (comparable == null) return false;
if (!(floor > 0)) return false;
if (!(rate >= comparable)) return false;
return rate >= floor;

PART_TIME_HOURS.validate:
// Labor Contract Law art.68: Keeps part-time terms within four hours a day and twenty-four hours a week.
