MEDICAL_PERIOD_EXHAUSTED.validate:
// 劳部发〔1994〕479号 第三条 (3/6/9/12/18/24个月); 沪府发〔2015〕40号 (上海第1年3个月, 每满1年加1个月, 上限24个月); 劳部发〔1995〕236号
const catalog = ctx.reads.leave_catalog.find((row) => row.code === ctx.entry.catalog_code);
if (catalog == null || catalog.code !== 'SICK_LEAVE') return true;
const emp = ctx.subject.employment;
const employerRegion = String(get(ctx.subject.employer, 'statutory_parameters.region', ''));
const worksite = String(get(emp, 'terms.work_region', ''));
const region = worksite !== '' ? worksite : employerRegion;
const totalStarted = get(emp, 'service_started_on', emp.effective_range.from);
const unitStarted = get(emp, 'employment_started_on', emp.effective_range.from);
const maxMonthsAt = (onDate) => {
	const unitYears = Math.floor(calendar_completed_months(unitStarted, onDate) / 12);
	if (region === 'SH') return Math.min(24, 3 + Math.max(0, unitYears));
	const totalYears = Math.floor(calendar_completed_months(totalStarted, onDate) / 12);
	if (totalYears < 10) return unitYears < 5 ? 3 : 6;
	if (unitYears < 5) return 6;
	if (unitYears < 10) return 9;
	if (unitYears < 15) return 12;
	if (unitYears < 20) return 18;
	return 24;
};
const illnesses = get(emp, 'events', []).filter((event) => event.kind === 'ILLNESS');
const own = get(ctx.entry, 'leave_catalog_entry_day', []);
const expired = own.some((child) => illnesses.some((event) =>
	event.on <= String(child.incurred_on) &&
	(get(event, 'ended_on', null) == null || String(child.incurred_on) <= event.ended_on) &&
	calendar_completed_months(event.on, String(child.incurred_on)) >= maxMonthsAt(String(child.incurred_on))
));
if (expired && get(emp, 'statutory_parameters.medical_period_extension', null) == null)
	throw 'This illness has run its statutory medical period. Record the approved extension on the contract first.';
const used = sum((ctx.reads.leave_catalog_entry ?? []).filter((e) => e.id !== get(ctx.entry, 'id', '') && e.catalog_code === ctx.entry.catalog_code).map((e) => (ctx.reads.leave_catalog_entry_day ?? []).filter((child) => child.leave_entry_id === e.id).length / 2)) + own.length / 2;
if (used <= ctx.lookup.review_after_days) return true;
return get(emp, 'statutory_parameters.medical_period_review', null) != null;

WORK_INJURY_LEAVE_12_MONTHS.validate:
// 工伤保险条例 第三十三条第二款: 停工留薪期一般不超过12个月, 经设区的市级劳动能力鉴定委员会确认可延长, 但延长不得超过12个月 (总计24个月上限)
if (ctx.entry.catalog_code !== 'WORK_INJURY_LEAVE') return true;
const own = get(ctx.entry, 'leave_catalog_entry_day', []);
const used = sum((ctx.reads.leave_catalog_entry ?? []).filter((e) => e.id !== get(ctx.entry, 'id', '') && e.catalog_code === ctx.entry.catalog_code).map((e) => (ctx.reads.leave_catalog_entry_day ?? []).filter((child) => child.leave_entry_id === e.id).length / 2)) + own.length / 2;
if (used > ctx.lookup.hard_maximum_days) return false;
if (used <= ctx.lookup.maximum_days) return true;
return get(ctx.subject.employment, 'statutory_parameters.work_injury_leave_extension', null) != null;

