OVER_AGE_AGREEMENT.condition:
// 超龄劳动者基本权益保障暂行规定 (人社部令第56号, 2026-07-01起) 第二条、第六条: trigger condition.
const key = 'OVER_AGE_AGREEMENT:' + ctx.entry.employment_id;
if (ctx.reads.obligation.some((task) => task.occurrence_key === key)) return false;
const run = first(ctx.reads.payroll_run);
if (run == null) return false;
if (['CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(ctx.subject.employment.engagement)) return false;
const born = get(ctx.subject.employment, 'payroll.date_of_birth', null);
if (born == null || born === '') return false;
const category =
get(ctx.subject.employment, 'payroll.gender', null) === 'FEMALE'
? get(ctx.subject.employment, 'statutory_parameters.retirement_category', 'FEMALE_50')
: 'MALE';
const retirement = ctx.lookup.retirement.find((row) => row.category === category);
const deferred =
born < retirement.cutoff
? 0
: Math.min(
retirement.max_deferral_months,
Math.trunc(calendar_completed_months(retirement.cutoff, month_start(born)) / retirement.birth_months_per_step) + 1
);
const retires = add_months(born, retirement.base_years * 12 + deferred);
if (run.salary_coverage.from < retires) return false;
return get(ctx.subject.employment, 'terms.signed_on', '') < retires;

OVER_AGE_AGREEMENT.effects:
// 超龄劳动者基本权益保障暂行规定 (人社部令第56号, 2026-07-01起) 第二条、第六条: obligation/deadline emission.
return [{
  entity_id: ctx.entry.entity_id,
  employee_id: ctx.entry.employee_id,
  employment_id: ctx.entry.employment_id,
  title: ctx.lookup.title,
  due_on: first(ctx.reads.payroll_run).pay_date,
  occurrence_key: 'OVER_AGE_AGREEMENT:' + ctx.entry.employment_id
}];

PENSION.eligibility:
const engagement = get(ctx.subject.employment, 'engagement', 'EMPLOYEE');
	const excluded = ['PART_TIME', 'INTERN', 'CONTRACTOR', 'CONSULTANT', 'PAYEE'].includes(engagement);
	const end = get(ctx.subject.employment, 'effective_range.to', null);
	const ended = end != null && end !== '' && end < ctx.run.salary_coverage.from;
	const exempt = get(ctx.subject.employment, 'statutory_parameters.si_exempt_schemes', []);
	// a monthly charge: an off-cycle run carries only its own items
	if (get(ctx.run, 'kind', 'ON_CYCLE') === 'OFF_CYCLE') return false;
	if (excluded) return false;
	if (ended) return false;
	if (Array.isArray(exempt) && exempt.includes('PENSION')) return false;
	const born = get(ctx.subject.employment, 'payroll.date_of_birth', null);
	if (born == null || born === '') return true;
	// 人社部令第56号 第十六条、第十七条: past the statutory retirement date this scheme stops, unless an agreement signed on or after that date declares a contribution base
	const category =
		get(ctx.subject.employment, 'payroll.gender', null) === 'FEMALE'
			? get(ctx.subject.employment, 'statutory_parameters.retirement_category', 'FEMALE_50')
			: 'MALE';
	const retirement = ctx.lookup.retirement.find((row) => row.category === category);
	const deferred =
		born < retirement.cutoff
			? 0
			: Math.min(
					retirement.max_deferral_months,
					Math.trunc(calendar_completed_months(retirement.cutoff, month_start(born)) / retirement.birth_months_per_step) + 1
				);
	const retires = add_months(born, retirement.base_years * 12 + deferred);
	if (ctx.run.salary_coverage.from < retires) return true;
	if (get(ctx.subject.employment, 'statutory_parameters.si_contribution_base', null) == null) return false;
	return get(ctx.subject.employment, 'terms.signed_on', '') >= retires;

